const categories=[{name:'Medicines',icon:'✚',tint:'#e9f2eb'},{name:'Baby Care',icon:'♧',tint:'#fff1e1'},{name:'Personal Care',icon:'✿',tint:'#f4eaf1'},{name:'Vitamins & Wellness',icon:'☀',tint:'#fff5d9'},{name:'Healthcare Devices',icon:'♡',tint:'#e7f1fa'},{name:'First Aid',icon:'⊞',tint:'#e7f3ee'}];
const products=[{name:'Everyday medicine essentials',category:'Medicines',label:'MEDICINE',accent:'#238575',description:'Explore medicine availability with the store team. Bring the exact name, strength and prescription where applicable.'},{name:'Baby care essentials',category:'Baby Care',label:'BABY CARE',accent:'#cba05c',description:'Explore everyday baby care items. Ask in store about available brands, pack sizes and prices.'},{name:'Daily skin care',category:'Personal Care',label:'SKIN CARE',accent:'#b88f9f',description:'Browse skin care product types and check the available options in store.'},{name:'Vitamins & supplements',category:'Vitamins & Wellness',label:'WELLNESS',accent:'#d2ab4f',description:'Ask in store about available vitamins and supplements. Product suitability should be discussed with a qualified healthcare professional.'},{name:'Digital thermometers',category:'Healthcare Devices',label:'HEALTHCARE',accent:'#6291ae',description:'Check available thermometer models, instructions and pricing with the store.'},{name:'First aid essentials',category:'First Aid',label:'FIRST AID',accent:'#448b75',description:'Explore bandages, dressings and other first aid product types. Actual stock is to be confirmed.'},{name:'Oral care essentials',category:'Personal Care',label:'ORAL CARE',accent:'#549890',description:'Ask about available toothbrushes, toothpaste and other oral care essentials.'},{name:'Baby hygiene',category:'Baby Care',label:'GENTLE CARE',accent:'#b89a75',description:'Check in store for available baby hygiene products, pack sizes and prices.'}];
let active='All essentials';const search=document.querySelector('#search');const grid=document.querySelector('#products');
document.querySelector('#year').textContent=new Date().getFullYear();
document.querySelector('#category-grid').innerHTML=categories.map((c,i)=>`<button class="category" data-category="${i}" style="--tint:${c.tint}"><span class="icon" aria-hidden="true">${c.icon}</span><strong>${c.name}</strong></button>`).join('');
const filters=document.querySelector('#filters');filters.innerHTML=['All essentials',...categories.map(c=>c.name)].map(c=>`<button type="button" aria-pressed="${c===active}">${c}</button>`).join('');
function render(){const query=search.value.trim().toLowerCase();const matches=products.filter(p=>(active==='All essentials'||p.category===active)&&`${p.name} ${p.category}`.toLowerCase().includes(query));grid.innerHTML=matches.map(p=>{const c=categories.find(c=>c.name===p.category);return `<article class="product"><div class="product-image" aria-hidden="true" style="--tint:${c.tint};--accent:${p.accent}"><div class="object"><span>${p.label}</span><small>ILLUSTRATION</small></div></div><span class="tag">${p.category}</span><h3>${p.name}</h3><p>Check availability in store</p><button data-product="${products.indexOf(p)}" aria-label="View details for ${p.name}">View details</button></article>`}).join('');document.querySelector('#empty').hidden=matches.length>0;document.querySelector('#result-count').textContent=`${matches.length} sample product types shown`;filters.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.textContent===active)))}
filters.addEventListener('click',e=>{if(e.target.tagName==='BUTTON'){active=e.target.textContent;render()}});
document.querySelector('#category-grid').addEventListener('click',e=>{const b=e.target.closest('button');if(b){active=categories[Number(b.dataset.category)].name;search.value='';render();document.querySelector('#catalogue').scrollIntoView({behavior:'smooth'})}});
search.addEventListener('input',render);document.querySelector('#search-form').addEventListener('submit',e=>{e.preventDefault();render();document.querySelector('#catalogue').scrollIntoView({behavior:'smooth'})});
document.querySelector('#reset').addEventListener('click',()=>{search.value='';active='All essentials';render()});
const dialog=document.querySelector('#detail');grid.addEventListener('click',e=>{const b=e.target.closest('[data-product]');if(!b)return;const p=products[Number(b.dataset.product)];document.querySelector('#detail-content').innerHTML=`<span class="eyebrow">${p.category}</span><h2>${p.name}</h2><p>${p.description}</p>`;dialog.showModal()});dialog.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>dialog.close()));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});render();
